// WIRED 17 August 2026, task #116, Phase C.
//
// ── FOUR OF THIS SCREEN'S SIX SECTIONS HAD NO DATA BEHIND THEM ───────────
//
// The Stitch version showed check-in and check-out times, the host's name and
// phone number, written access instructions, and a map. Checked against the
// model before rebuilding:
//
//   check-in / check-out times   NOT on StayListing. Not collected by the
//                                host wizard either.
//   access instructions          Same. No field, nowhere to enter one.
//   house rules                  Same.
//   host name / phone            Guests cannot read /stay_hosts under the
//                                security rules. Same wall screen 05 hit with
//                                "Hosted by Sarah".
//
// So this was not an unwired screen. It was a screen describing a product that
// does not exist yet, and wiring it would have meant inventing a check-in time
// for somebody's holiday.
//
// What it shows instead is everything that IS real and that a guest actually
// needs while travelling: where the property is, when they are there, the
// photographs that protect their deposit, and the GoOuts partners around them
// — which is the one thing on this screen no other platform could show.
//
// ⚠ THE MISSING FIELDS ARE A HOST WIZARD JOB, NOT A SCREEN JOB. Adding
// checkInTime, checkOutTime and arrivalInstructions to the listing model and
// to host_04 is what unblocks the rest of this screen. Until then, the note at
// the bottom tells the guest the truth: the host sends arrival details
// directly.
import 'package:flutter/material.dart';
import 'package:google_fonts/google_fonts.dart';

import '../models/stay_booking.dart';
import '../models/stay_enums.dart';
import '../models/stay_evidence.dart';
import '../models/stay_listing.dart';
import '../services/stay_booking_service.dart';
import '../services/stay_evidence_service.dart';
import '../services/stay_listing_service.dart';
import '../stay_routes.dart';
import '../theme/stay_colors.dart';

class TripDetailsScreen extends StatefulWidget {
  const TripDetailsScreen({super.key, required this.bookingId});

  final String bookingId;

  @override
  State<TripDetailsScreen> createState() => _TripDetailsScreenState();
}

class _TripDetailsScreenState extends State<TripDetailsScreen> {
  StayListing? _listing;
  String? _loadedFor;

  void _ensureListing(String listingId) {
    if (listingId.isEmpty || _loadedFor == listingId) return;
    _loadedFor = listingId;
    StayListingService.instance.byId(listingId).then((l) {
      if (!mounted) return;
      setState(() => _listing = l);
    }).catchError((_) => null);
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: GoOutsColors.background,
      appBar: AppBar(
        backgroundColor: Colors.white,
        elevation: 0.5,
        leading: IconButton(
          icon: const Icon(Icons.arrow_back, color: GoOutsColors.primaryBlue),
          onPressed: () => Navigator.of(context).pop(),
        ),
        title: Text(
          'Your trip',
          style: GoogleFonts.inter(
            fontSize: 20,
            fontWeight: FontWeight.bold,
            color: GoOutsColors.deepNavy,
          ),
        ),
      ),
      // The fake bottom navigation bar is gone — four dead labels on a pushed
      // screen, same as screen 14 had.
      body: StreamBuilder<StayBooking?>(
        stream: StayBookingService.instance.watch(widget.bookingId),
        builder: (context, snapshot) {
          if (snapshot.connectionState == ConnectionState.waiting) {
            return const Center(child: CircularProgressIndicator());
          }
          final StayBooking? b = snapshot.data;
          if (b == null) {
            return Center(
              child: Padding(
                padding: const EdgeInsets.all(32),
                child: Text('This trip could not be loaded.',
                    style: GoogleFonts.inter(
                        fontSize: 15, color: GoOutsColors.bodyText)),
              ),
            );
          }
          _ensureListing(b.listingId);

          return ListView(
            padding: const EdgeInsets.all(16),
            children: [
              _header(b),
              const SizedBox(height: 16),
              _whenCard(b),
              const SizedBox(height: 16),
              _addressCard(),
              const SizedBox(height: 16),
              _photosCard(b),
              if (_listing?.locationContext != null) ...[
                const SizedBox(height: 16),
                _partnersCard(_listing!.locationContext!),
              ],
              const SizedBox(height: 16),
              _arrivalNote(),
              const SizedBox(height: 24),
            ],
          );
        },
      ),
    );
  }

  Widget _card(Widget child) => Container(
        padding: const EdgeInsets.all(16),
        decoration: BoxDecoration(
          color: Colors.white,
          borderRadius: BorderRadius.circular(12),
        ),
        child: child,
      );

  static const List<String> _months = <String>[
    'January', 'February', 'March', 'April', 'May', 'June',
    'July', 'August', 'September', 'October', 'November', 'December',
  ];
  static String _d(DateTime d) => '${d.day} ${_months[d.month - 1]}';

  // ── Header ───────────────────────────────────────────────────────────────

  Widget _header(StayBooking b) {
    final List<StayPhoto> photos =
        List<StayPhoto>.from(_listing?.photos ?? const <StayPhoto>[])
          ..sort((a, b2) => a.order.compareTo(b2.order));

    return ClipRRect(
      borderRadius: BorderRadius.circular(12),
      child: Stack(
        children: [
          photos.isEmpty
              ? Container(
                  height: 160,
                  width: double.infinity,
                  color: GoOutsColors.paleBlueTint,
                  child: const Icon(Icons.home_outlined,
                      size: 48, color: GoOutsColors.primaryBlue),
                )
              : Image.network(
                  photos.first.url,
                  height: 160,
                  width: double.infinity,
                  fit: BoxFit.cover,
                  errorBuilder: (_, __, ___) => Container(
                    height: 160,
                    color: GoOutsColors.paleBlueTint,
                  ),
                ),
          Positioned(
            left: 0,
            right: 0,
            bottom: 0,
            child: Container(
              padding: const EdgeInsets.all(12),
              color: Colors.black.withValues(alpha: 0.45),
              child: Text(
                _listing?.title ?? 'Your stay',
                style: GoogleFonts.inter(
                  fontSize: 17,
                  fontWeight: FontWeight.bold,
                  color: Colors.white,
                ),
              ),
            ),
          ),
        ],
      ),
    );
  }

  // ── When ─────────────────────────────────────────────────────────────────
  //
  // Dates only. NOT times — the listing has no checkInTime or checkOutTime and
  // the host wizard does not ask for one, so any clock shown here would have
  // been chosen by this screen rather than by the host.

  Widget _whenCard(StayBooking b) {
    final int nightsLeft = b.checkOut.difference(DateTime.now()).inDays;

    return _card(
      Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Text('When',
              style: GoogleFonts.inter(
                  fontSize: 16,
                  fontWeight: FontWeight.bold,
                  color: GoOutsColors.deepNavy)),
          const SizedBox(height: 12),
          Row(
            children: [
              Expanded(child: _fact('Arrive', _d(b.checkIn))),
              Expanded(child: _fact('Leave', _d(b.checkOut))),
              Expanded(
                child: _fact('Nights', '${b.nights}'),
              ),
            ],
          ),
          if (b.status == BookingStatus.inProgress && nightsLeft >= 0) ...[
            const SizedBox(height: 12),
            Text(
              nightsLeft == 0
                  ? 'You leave today.'
                  : 'You have $nightsLeft '
                      '${nightsLeft == 1 ? 'night' : 'nights'} left.',
              style: GoogleFonts.inter(
                  fontSize: 13.5, color: GoOutsColors.bodyText),
            ),
          ],
        ],
      ),
    );
  }

  Widget _fact(String label, String value) => Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Text(label,
              style: GoogleFonts.inter(
                  fontSize: 12, color: GoOutsColors.bodyText)),
          const SizedBox(height: 2),
          Text(value,
              style: GoogleFonts.inter(
                  fontSize: 15,
                  fontWeight: FontWeight.w700,
                  color: GoOutsColors.deepNavy)),
        ],
      );

  // ── Where ────────────────────────────────────────────────────────────────
  //
  // The real address. This is the single most useful thing on the screen for
  // somebody actually travelling, and it was not on the Stitch version at all
  // — that had a map picture instead.

  Widget _addressCard() {
    final StayAddress? a = _listing?.address;
    if (a == null || (a.line1.isEmpty && a.postcode.isEmpty)) {
      return const SizedBox.shrink();
    }

    final String full = <String>[
      if (a.line1.isNotEmpty) a.line1,
      if (a.town.isNotEmpty) a.town,
      if (a.postcode.isNotEmpty) a.postcode,
    ].join(', ');

    return _card(
      Row(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          const Icon(Icons.place_outlined, color: GoOutsColors.primaryBlue),
          const SizedBox(width: 12),
          Expanded(
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text('Address',
                    style: GoogleFonts.inter(
                        fontSize: 16,
                        fontWeight: FontWeight.bold,
                        color: GoOutsColors.deepNavy)),
                const SizedBox(height: 4),
                SelectableText(
                  full,
                  style: GoogleFonts.inter(
                      fontSize: 14.5,
                      height: 1.35,
                      color: GoOutsColors.bodyText),
                ),
              ],
            ),
          ),
        ],
      ),
    );
  }

  // ── Photographs ──────────────────────────────────────────────────────────

  Widget _photosCard(StayBooking b) {
    return StreamBuilder<List<StayEvidence>>(
      stream: StayEvidenceService.instance
          .watchKind(widget.bookingId, CaptureKind.guestCheckIn),
      builder: (context, snap) {
        final List<StayEvidence> taken =
            (snap.data ?? const <StayEvidence>[])
                .where((e) => !e.skipped)
                .toList(growable: false);

        return _card(
          Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Text('Arrival photographs',
                  style: GoogleFonts.inter(
                      fontSize: 16,
                      fontWeight: FontWeight.bold,
                      color: GoOutsColors.deepNavy)),
              const SizedBox(height: 4),
              Text(
                taken.isEmpty
                    ? 'Take these when you arrive. They are your evidence if a '
                        'damage claim is made.'
                    : '${taken.length} '
                        '${taken.length == 1 ? 'photograph' : 'photographs'} '
                        'held for your arrival.',
                style: GoogleFonts.inter(
                    fontSize: 13.5,
                    height: 1.35,
                    color: GoOutsColors.bodyText),
              ),
              const SizedBox(height: 12),
              Row(
                children: [
                  Expanded(
                    child: OutlinedButton.icon(
                      onPressed: () => Navigator.of(context).pushNamed(
                        StayRoutes.captureIntro,
                        arguments: <String, dynamic>{
                          'bookingId': b.id,
                          'captureKind': CaptureKind.guestCheckIn.wire,
                        },
                      ),
                      icon: const Icon(Icons.photo_camera_outlined, size: 18),
                      label: Text(taken.isEmpty ? 'Take them' : 'Add more'),
                      style: OutlinedButton.styleFrom(
                        minimumSize: const Size(0, 44),
                        foregroundColor: GoOutsColors.primaryBlue,
                        side: const BorderSide(
                            color: GoOutsColors.primaryBlue),
                      ),
                    ),
                  ),
                  if (taken.isNotEmpty) ...[
                    const SizedBox(width: 10),
                    Expanded(
                      child: TextButton(
                        onPressed: () => Navigator.of(context).pushNamed(
                          StayRoutes.evidencePack,
                          arguments: <String, dynamic>{'bookingId': b.id},
                        ),
                        child: const Text('View all'),
                      ),
                    ),
                  ],
                ],
              ),
            ],
          ),
        );
      },
    );
  }

  // ── Partners ─────────────────────────────────────────────────────────────
  //
  // The reason to book through GoOuts rather than anywhere else, and the most
  // useful thing on this screen once somebody has arrived.

  Widget _partnersCard(StayLocationContext ctx) {
    final int half = ctx.partnerCounts.halfMile;
    if (half <= 0) return const SizedBox.shrink();

    final List<StayNearbyPartner> nearest =
        ctx.nearestPartners.take(4).toList(growable: false);

    return Container(
      padding: const EdgeInsets.all(16),
      decoration: BoxDecoration(
        color: GoOutsColors.primaryBlue,
        borderRadius: BorderRadius.circular(12),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Text(
            '$half GoOuts ${half == 1 ? 'partner' : 'partners'} '
            'within half a mile',
            style: GoogleFonts.inter(
                fontSize: 16,
                fontWeight: FontWeight.bold,
                color: Colors.white),
          ),
          const SizedBox(height: 4),
          Text(
            'Earn cashback on your coffee, dinner and shopping while you are '
            'here.',
            style: GoogleFonts.inter(
                fontSize: 13.5,
                height: 1.35,
                color: Colors.white.withValues(alpha: 0.9)),
          ),
          if (nearest.isNotEmpty) ...[
            const SizedBox(height: 12),
            for (final p in nearest)
              Padding(
                padding: const EdgeInsets.only(bottom: 6),
                child: Row(
                  children: [
                    const Icon(Icons.storefront_outlined,
                        size: 16, color: Colors.white),
                    const SizedBox(width: 8),
                    Expanded(
                      child: Text(
                        p.name,
                        overflow: TextOverflow.ellipsis,
                        style: GoogleFonts.inter(
                            fontSize: 13.5, color: Colors.white),
                      ),
                    ),
                    Text(
                      '${p.walkMi.toStringAsFixed(1)} mi',
                      style: GoogleFonts.inter(
                          fontSize: 12,
                          color: Colors.white.withValues(alpha: 0.85)),
                    ),
                  ],
                ),
              ),
          ],
        ],
      ),
    );
  }

  // ── The honest note ──────────────────────────────────────────────────────

  Widget _arrivalNote() => Container(
        padding: const EdgeInsets.all(14),
        decoration: BoxDecoration(
          color: GoOutsColors.infoBlueBg,
          borderRadius: BorderRadius.circular(12),
        ),
        child: Row(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            const Icon(Icons.info_outline,
                size: 18, color: GoOutsColors.primaryBlue),
            const SizedBox(width: 10),
            Expanded(
              child: Text(
                // True today. Check-in times and access instructions are not
                // fields on a listing yet, so the host really does send them
                // directly. Saying so is better than printing a time nobody
                // agreed to.
                'Your host will send arrival times and how to get in. If you '
                'have not heard from them, contact us and we will chase it.',
                style: GoogleFonts.inter(
                    fontSize: 13,
                    height: 1.35,
                    color: GoOutsColors.bodyText),
              ),
            ),
          ],
        ),
      );
}
